    content.style.cssText = CONTENT_MAX_700;
    const {
      element: logEl,
      log: logFn
    } = createLogPanel();
    const info = document.createElement('div');
    info.style.cssText = INFO_MUTED_STYLE;
    info.textContent = 'Fallback JSON editor for policy types without a custom editor. Try editing the JSON — invalid JSON shows an error.';
