    info.style.cssText = INFO_STYLE;
    info.innerHTML = ['<strong>Callback demo:</strong> Select a policy, modify it, and use Save/Reset/Apply buttons.', '- <em>Save</em> persists changes to the catalog store and fires onPolicySaved.', '- <em>Reset</em> reverts the editor draft to the last saved state.', '- <em>Apply</em> fires onPolicyApplied with the current data (for immediate use in tournament).', 'Check the Event Log below for callback invocations.'].join('<br>');
    root.appendChild(info);
    const container = document.createElement('div');
    container.style.height = 'calc(100vh - 250px)';
    root.appendChild(container);
